ALTER TABLE public.platform_subscriptions ADD COLUMN trial_package_only boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.platform_subscriptions.trial_package_only IS 'HQ explicit immediate tier access during trial; trial dates and issued invoices are retained.';
CREATE OR REPLACE FUNCTION public.platform_subscription_module_access(_subscription uuid,_module text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.platform_subscriptions; p public.platform_products; o boolean; BEGIN SELECT * INTO s FROM public.platform_subscriptions WHERE id=_subscription; IF NOT FOUND THEN RETURN false; END IF; IF s.status='legacy' THEN RETURN true; END IF; IF s.status='trial' AND s.trial_ends_at<=now() THEN RETURN false; END IF; IF s.status NOT IN('trial','active') THEN RETURN false; END IF; IF public.company_invoice_lapsed(s.id) THEN RETURN false; END IF; IF _module='core' THEN RETURN true; END IF; SELECT enabled INTO o FROM public.platform_overrides WHERE subscription_id=s.id AND module=_module AND starts_at<=now() AND ends_at>now() ORDER BY created_at DESC,id DESC LIMIT 1; IF FOUND THEN RETURN o; END IF; IF s.status='trial' AND NOT s.trial_package_only THEN RETURN true; END IF; SELECT * INTO p FROM public.platform_products WHERE id=s.product_id; IF NOT(_module=ANY(p.modules)) THEN RETURN true; END IF; RETURN EXISTS(SELECT 1 FROM public.platform_catalog c WHERE c.product_id=s.product_id AND (c.id=s.plan_id OR c.id=ANY(s.pack_ids)) AND _module=ANY(c.modules)); END $$;
CREATE OR REPLACE FUNCTION public.hq_apply_setup_now(_subscription uuid,_plan uuid,_packs uuid[],_seats integer,_cadence text,_price numeric,_modes jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.platform_subscriptions; module text; mode text; BEGIN IF NOT public.is_platform_owner() THEN RAISE EXCEPTION 'Platform owner access required'; END IF; SELECT * INTO s FROM public.platform_subscriptions WHERE id=_subscription FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable'; END IF; IF _seats<0 OR _price<0 OR _cadence NOT IN('monthly','quarterly','yearly') OR jsonb_typeof(_modes)<>'object' THEN RAISE EXCEPTION 'Invalid package settings'; END IF; UPDATE public.platform_subscriptions SET plan_id=_plan,pack_ids=coalesce(_packs,'{}'),seats=_seats,cadence=_cadence,agreed_price=_price,pending_change=NULL,trial_package_only=(_plan IS NOT NULL) WHERE id=s.id; DELETE FROM public.platform_overrides WHERE subscription_id=s.id AND reason='Initial setup package'; FOR module,mode IN SELECT key,value FROM jsonb_each_text(_modes) LOOP IF mode NOT IN('on','off','package') THEN RAISE EXCEPTION 'Invalid module mode'; END IF; IF module<>'core' AND mode<>'package' THEN INSERT INTO public.platform_overrides(subscription_id,module,enabled,starts_at,ends_at,reason) VALUES(s.id,module,mode='on',now(),'2099-12-31T23:59:59Z','Initial setup package'); END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.hq_apply_setup_now(uuid,uuid,uuid[],integer,text,numeric,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hq_apply_setup_now(uuid,uuid,uuid[],integer,text,numeric,jsonb) TO authenticated;